import { logger } from '@lark-apaas/client-toolkit-lite';
import type { I18nText } from '@/lib/i18n-text';

/**
 * 翻译服务封装 —— 支持 DeepL（需 API Key）与 MyMemory（免费兜底）双引擎
 * - 优先 DeepL：质量更高，需用户配置 API Key
 * - 兜底 MyMemory：免费免 Key，前端可直接调用
 * - 统一 localStorage 缓存，避免重复翻译
 */

const CACHE_KEY = '__app_ledlight_translation_cache_v2';
const SETTINGS_KEY = '__app_ledlight_translate_settings';
const SETTINGS_CHANGE_EVENT = 'translate-settings-change';

// 内存中的当前设置（在 save 后更新，供同步读取使用）
let inMemorySettings: TranslateSettings | null = null;

type LangCode = 'en' | 'zh' | 'es' | 'ja';

// MyMemory 语言代码映射
const MYMEMORY_LANG_MAP: Record<LangCode, string> = {
  en: 'en',
  zh: 'zh-CN',
  es: 'es',
  ja: 'ja',
};

// DeepL 语言代码映射（大写）
const DEEPL_LANG_MAP: Record<LangCode, string> = {
  en: 'EN',
  zh: 'ZH',
  es: 'ES',
  ja: 'JA',
};

/** 翻译设置 */
export interface TranslateSettings {
  provider: 'deepl' | 'mymemory';
  deeplApiKey: string;
  deeplPlan: 'free' | 'pro';
  useCorsProxy: boolean;
  corsProxyApiKey: string;
  customProxyUrl: string;
}

const DEFAULT_SETTINGS: TranslateSettings = {
  provider: 'mymemory',
  deeplApiKey: '',
  deeplPlan: 'free',
  useCorsProxy: true,
  corsProxyApiKey: '',
  customProxyUrl: '',
};

/* ---------- 设置读写 ---------- */

export function getTranslateSettings(): TranslateSettings {
  try {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      const merged = { ...DEFAULT_SETTINGS, ...parsed };
      inMemorySettings = merged;
      return merged;
    }
  } catch {
    // ignore
  }
  return { ...DEFAULT_SETTINGS };
}

export function saveTranslateSettings(settings: TranslateSettings) {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
    inMemorySettings = settings;
    // 触发同 tab 内刷新事件
    if (typeof window !== 'undefined') {
      try {
        window.dispatchEvent(
          new CustomEvent(SETTINGS_CHANGE_EVENT, { detail: settings })
        );
      } catch {
        /* ignore */
      }
    }
  } catch (e) {
    logger.warn('Failed to save translate settings: ' + String(e));
  }
}

/** 监听设置变化（供 hook/页面使用） */
export function subscribeTranslateSettings(
  callback: (settings: TranslateSettings) => void
): () => void {
  if (typeof window === 'undefined') return () => {};
  const handler = (e: Event) => {
    const detail = (e as CustomEvent<TranslateSettings>).detail;
    if (detail && typeof detail === 'object') {
      const merged = { ...DEFAULT_SETTINGS, ...detail };
      inMemorySettings = merged;
      callback(merged);
    }
  };
  // 也监听 storage 事件（跨 tab）
  const storageHandler = (e: StorageEvent) => {
    if (e.key !== SETTINGS_KEY || !e.newValue) return;
    try {
      const parsed = JSON.parse(e.newValue);
      const merged = { ...DEFAULT_SETTINGS, ...parsed };
      inMemorySettings = merged;
      callback(merged);
    } catch {
      /* ignore */
    }
  };
  window.addEventListener(SETTINGS_CHANGE_EVENT, handler);
  window.addEventListener('storage', storageHandler);
  return () => {
    window.removeEventListener(SETTINGS_CHANGE_EVENT, handler);
    window.removeEventListener('storage', storageHandler);
  };
}

/* ---------- 缓存 ---------- */

interface CacheEntry {
  [key: string]: string;
}

let cache: CacheEntry | null = null;

function getCache(): CacheEntry {
  if (cache) return cache;
  try {
    const saved = localStorage.getItem(CACHE_KEY);
    cache = saved ? JSON.parse(saved) : {};
  } catch {
    cache = {};
  }
  return cache!;
}

function saveCache() {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
  } catch (e) {
    logger.warn('Failed to save translation cache: ' + String(e));
  }
}

function cacheKey(from: LangCode, to: LangCode, text: string): string {
  return `${from}|${to}|${text.trim()}`;
}

/* ---------- 简单令牌桶限流 ---------- */

class RateLimiter {
  private tokens: number;
  private lastRefill: number;
  private readonly rate: number; // 每秒补充 token 数
  private readonly max: number;

  constructor(perSecond = 2, maxBurst = 5) {
    this.rate = perSecond;
    this.max = maxBurst;
    this.tokens = maxBurst;
    this.lastRefill = Date.now();
  }

  async acquire(): Promise<void> {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.max, this.tokens + elapsed * this.rate);
    this.lastRefill = now;

    if (this.tokens >= 1) {
      this.tokens -= 1;
      return;
    }
    // 等待下一个 token
    const waitMs = (1 - this.tokens) / this.rate * 1000;
    await new Promise((r) => setTimeout(r, waitMs));
    this.tokens = 0;
    this.lastRefill = Date.now();
  }
}

// 全局限流器（DeepL 更稳：每秒 2 次，突发 5；MyMemory 更保守：每秒 1 次）
const deeplLimiter = new RateLimiter(2, 5);
const mymemoryLimiter = new RateLimiter(1, 3);

/* ---------- CORS 代理列表 ---------- */

// 多个免费 CORS 代理，按顺序尝试（第一个失败自动试下一个）
// 格式说明：
//   prefix:  前缀模式，直接拼 URL → `${proxy}${target}`
//   query:   查询参数模式 → `${proxy}${encodeURIComponent(target)}`
// 注意：只有支持 POST 的代理才放这里（DeepL 翻译是 POST 请求）
interface CorsProxy {
  name: string;
  url: string;
  mode: 'prefix' | 'query';
  // 该代理是否支持自定义 header 透传（proxy.cors.sh 支持 x-cors-api-key，其他不一定）
  supportsCustomHeaders: boolean;
}

const CORS_PROXIES: CorsProxy[] = [
  {
    name: 'proxy.cors.sh',
    url: 'https://proxy.cors.sh/',
    mode: 'prefix',
    supportsCustomHeaders: true,
  },
  {
    name: 'corsproxy.io',
    url: 'https://corsproxy.io/?',
    mode: 'query',
    supportsCustomHeaders: false,
  },
  {
    name: 'allorigins.win',
    url: 'https://api.allorigins.win/post?url=',
    mode: 'query',
    supportsCustomHeaders: false,
  },
];

/* ---------- DeepL 翻译 ---------- */

/**
 * 净化 HTTP header 值：移除所有非 ISO-8859-1 字符
 * HTTP headers 只能包含 Latin-1 字符（U+0000 ~ U+00FF）
 * 复制粘贴 API Key 时常见问题：零宽空格、全角字符、BOM 等
 */
function sanitizeHeaderValue(value: string, label: string): string {
  if (!value) return value;
  // 先 trim 首尾空格和常见不可见字符
  let cleaned = value.trim();
  // 逐个字符检查，保留 ISO-8859-1 范围内的字符 (code point 0-255)
  const originalLen = cleaned.length;
  cleaned = cleaned.split('').filter((ch) => ch.charCodeAt(0) <= 255).join('');
  if (cleaned.length !== originalLen) {
    const removed = originalLen - cleaned.length;
    logger.warn(
      `[Translate] sanitizeHeaderValue: removed ${removed} non-Latin-1 character(s) from ${label}. ` +
      `Original length: ${originalLen}, cleaned length: ${cleaned.length}`
    );
  }
  return cleaned;
}

async function translateWithDeepL(
  text: string,
  from: LangCode,
  to: LangCode,
  apiKey: string,
  plan: 'free' | 'pro',
  useCorsProxy: boolean,
  corsApiKey?: string,
  customProxyUrl?: string,
): Promise<string> {
  const base =
    plan === 'free'
      ? 'https://api-free.deepl.com/v2/translate'
      : 'https://api.deepl.com/v2/translate';

  // 净化 API Key 和 CORS Proxy Key，防止非 ISO-8859-1 字符导致 fetch 失败
  const cleanApiKey = sanitizeHeaderValue(apiKey, 'DeepL Auth Key');
  const cleanCorsKey = sanitizeHeaderValue(corsApiKey || '', 'CORS Proxy Key');

  logger.info(
    `[Translate] DeepL request: plan=${plan}, useCorsProxy=${useCorsProxy}, ` +
    `apiKeyLen=${cleanApiKey.length}, corsKeyLen=${cleanCorsKey.length}, baseUrl=${base}`
  );

  if (!cleanApiKey) {
    throw new Error('DeepL API key is empty after sanitization (check for non-Latin characters)');
  }

  const baseHeaders: Record<string, string> = {
    'Content-Type': 'application/x-www-form-urlencoded',
    Authorization: `DeepL-Auth-Key ${cleanApiKey}`,
  };

  // 脱敏打印 headers（Key 只显示首尾 4 字符，中间用 * 填充）
  function describeHeaders(headers: Record<string, string>): string {
    const parts: string[] = [];
    for (const [k, v] of Object.entries(headers)) {
      if (k.toLowerCase() === 'authorization') {
        const match = v.match(/^(.+?\s+)(.+)$/);
        if (match) {
          const prefix = match[1];
          const key = match[2];
          const masked = key.length <= 8
            ? '*'.repeat(key.length)
            : `${key.slice(0, 4)}${'*'.repeat(Math.max(4, key.length - 8))}${key.slice(-4)}`;
          parts.push(`${k}: ${prefix}${masked} (len=${key.length})`);
        } else {
          parts.push(`${k}: <masked>`);
        }
      } else if (k.toLowerCase().includes('api-key') || k.toLowerCase().includes('apikey')) {
        parts.push(`${k}: *** (len=${v.length})`);
      } else {
        parts.push(`${k}: ${v}`);
      }
    }
    return parts.join(', ');
  }

  const body = new URLSearchParams({
    text,
    source_lang: DEEPL_LANG_MAP[from],
    target_lang: DEEPL_LANG_MAP[to],
  }).toString();

  /**
   * 执行一次 DeepL API 调用（直接或通过某个 CORS 代理）
   */
  async function doFetch(options: {
    via: 'direct' | 'proxy' | 'custom';
    proxy?: CorsProxy;
    customUrl?: string;
  }): Promise<{ ok: boolean; status: number; result?: string; error?: string; isNetworkError: boolean; via: string }> {
    const { via, proxy, customUrl } = options;
    let url: string;
    const headers = { ...baseHeaders };
    const label =
      via === 'direct' ? 'direct'
      : via === 'custom' ? 'custom-proxy'
      : `proxy:${proxy?.name || 'unknown'}`;

    if (via === 'direct') {
      url = base;
    } else if (via === 'custom' && customUrl) {
      // V135: 自定义代理（Cloudflare Worker 等）
      // 方案：把 plan 放进 URL 路径（/free 或 /pro），Worker 从路径判断目标端点
      // 为什么用路径而不是 header？
      //   - 路径参数不会触发 CORS preflight
      //   - Authorization + Content-Type 是 preflight 的触发因素，但这俩是必需的
      //   - 多一个自定义 header（如 X-Deepl-Plan）不会让 preflight "更触发"，
      //     只要有一个非 simple header 就会发 preflight
      // 但用路径更简洁，减少 preflight 时 Allow-Headers 的匹配压力。
      // Worker 端需要在 Access-Control-Allow-Headers 中包含 Content-Type 和 Authorization。
      const planSuffix = plan === 'pro' ? '/pro' : '/free';
      // 如果 URL 已经有 /free 或 /pro 后缀，就不加了；否则追加
      if (customUrl.endsWith('/free') || customUrl.endsWith('/pro')) {
        url = customUrl;
      } else {
        url = `${customUrl}${planSuffix}`;
      }
    } else if (proxy) {
      if (proxy.mode === 'prefix') {
        url = `${proxy.url}${base}`;
      } else {
        url = `${proxy.url}${encodeURIComponent(base)}`;
      }
      // 只有代理支持自定义 header 且配置了 CORS Key 时才加
      if (proxy.supportsCustomHeaders && cleanCorsKey) {
        headers['x-cors-api-key'] = cleanCorsKey;
      }
    } else {
      throw new Error('Proxy mode requires a proxy config');
    }

    try {
      logger.info(
        `[Translate] DeepL (${label}) request: POST ${url}, ` +
        `headers={${describeHeaders(headers)}}, ` +
        `bodyLen=${body.length}, ` +
        `source_lang=${DEEPL_LANG_MAP[from]}, target_lang=${DEEPL_LANG_MAP[to]}`
      );
      const res = await fetch(url, { method: 'POST', headers, body });
      const ct = res.headers.get('content-type') || 'unknown';
      const aclo = res.headers.get('access-control-allow-origin') || '(none)';
      logger.info(
        `[Translate] DeepL (${label}) response: HTTP ${res.status}, content-type=${ct}, ` +
        `access-control-allow-origin=${aclo}, content-length=${res.headers.get('content-length') || '?'}`
      );
      if (!res.ok) {
        const errText = await res.text().catch(() => '');
        return {
          ok: false,
          status: res.status,
          error: errText || `HTTP ${res.status}`,
          isNetworkError: false,
          via: label,
        };
      }
      const data = await res.json();
      const translated = data?.translations?.[0]?.text;
      if (!translated) {
        return { ok: false, status: res.status, error: 'empty translation result', isNetworkError: false, via: label };
      }
      return { ok: true, status: res.status, result: translated, isNetworkError: false, via: label };
    } catch (fetchErr) {
      const msg = fetchErr instanceof Error ? fetchErr.message : String(fetchErr);
      logger.error(`[Translate] DeepL (${label}) fetch error: "${msg}", url=${url}`);
      return { ok: false, status: 0, error: msg, isNetworkError: true, via: label };
    }
  }

  // 🔄 多通道轮询策略：
  // 优先级：
  // 1. 如果配置了自定义代理 URL（Cloudflare Worker 等）→ 优先使用（最稳定，无 CORS 问题）
  // 2. 用户选了 CORS Proxy → 依次尝试所有 CORS 代理，都失败了再试直连
  // 3. 用户没选 CORS Proxy → 先试直连，失败了再依次尝试所有 CORS 代理
  // 为什么要多代理？因为不同环境（妙搭平台 / GitHub Pages / 本地开发 / 企业网络）下
  // 不同代理的可用性完全不同，多代理兜底最大化成功率。
  // HTTP 4xx/5xx 是业务错误（API Key 错、超额度等），这种情况换通道也没用，直接返回错误。

  const attempts: Array<{ via: 'custom' | 'direct' | 'proxy'; proxy?: CorsProxy; customUrl?: string }> = [];

  // 自定义代理优先级最高
  // URL 标准化：trim + 去末尾斜杠 + 校验
  let cleanCustomUrl = (customProxyUrl || '').trim();
  if (cleanCustomUrl) {
    // 去末尾斜杠（但保留协议后的双斜杠 https://）
    cleanCustomUrl = cleanCustomUrl.replace(/\/+$/, '');
    // 基本校验
    const urlValid = /^https?:\/\/.+/.test(cleanCustomUrl);
    if (urlValid) {
      logger.info(`[Translate] Custom proxy URL configured: ${cleanCustomUrl} (will be used as highest priority)`);
      attempts.push({ via: 'custom', customUrl: cleanCustomUrl });
    } else {
      logger.warn(`[Translate] Custom proxy URL is invalid, ignoring: "${cleanCustomUrl}"`);
      cleanCustomUrl = '';
    }
  }

  if (useCorsProxy && !cleanCustomUrl) {
    // 先试所有 CORS 代理
    for (const p of CORS_PROXIES) {
      attempts.push({ via: 'proxy', proxy: p });
    }
    // 最后试直连（虽然大概率 CORS，但万一环境允许呢）
    attempts.push({ via: 'direct' });
  } else if (!useCorsProxy && !cleanCustomUrl) {
    // 先试直连
    attempts.push({ via: 'direct' });
    // 失败了试所有 CORS 代理
    for (const p of CORS_PROXIES) {
      attempts.push({ via: 'proxy', proxy: p });
    }
  }

  logger.info(
    `[Translate] DeepL attempt plan: ${attempts.map(a => {
      if (a.via === 'direct') return 'direct';
      if (a.via === 'custom') return 'custom-proxy';
      return 'proxy:' + a.proxy?.name;
    }).join(' → ')}`
  );

  let lastResult: Awaited<ReturnType<typeof doFetch>> | null = null;
  const failedAttempts: string[] = [];

  for (const attempt of attempts) {
    const result = await doFetch(attempt);
    lastResult = result;

    if (result.ok && result.result) {
      if (failedAttempts.length > 0) {
        logger.info(
          `[Translate] DeepL succeeded via ${result.via} after ${failedAttempts.length} failed attempt(s): ${failedAttempts.join(', ')}`
        );
      }
      return result.result;
    }

    failedAttempts.push(result.via);

    // HTTP 业务错误（非网络错误）→ 不用再试其他通道了，Key 错/超额度等换代理也没用
    if (!result.isNetworkError && result.status > 0) {
      logger.info(
        `[Translate] DeepL got HTTP ${result.status} via ${result.via} — stopping retry chain (business error, proxy won't help)`
      );
      break;
    }
  }

  // 全部失败，按错误类型返回友好消息
  const final = lastResult!;

  if (!final.isNetworkError && final.status > 0) {
    // HTTP 业务错误
    const status = final.status;
    const errBody = final.error || '';
    let errMsg = `HTTP ${status}`;

    if (status === 403) {
      // 🔍 诊断 403 是来自 DeepL 本身还是来自中间代理
      // - DeepL 返回的 403 body 含 "Forbidden" 或 "Missing Authorization header"
      // - 代理/CF 返回的 403 body 含 "Cloudflare" / "Forbidden. You don't have permission" / "keyless_legacy_url" 等
      const lowerBody = errBody.toLowerCase();
      const isFromDeepL = lowerBody.includes('deepl') ||
                          lowerBody.includes('forbidden') && !lowerBody.includes('cloudflare') && !lowerBody.includes("you don't have permission") ||
                          lowerBody.includes('missing authorization header') ||
                          lowerBody.includes('auth_key');
      const isProxyError = lowerBody.includes('cloudflare') ||
                           lowerBody.includes("you don't have permission") ||
                           lowerBody.includes('keyless_legacy_url') ||
                           lowerBody.includes('access denied') ||
                           lowerBody.includes('blocked');

      if (isProxyError && failedAttempts.length > 0) {
        // 403 是 CORS 代理返回的（不是 DeepL 返回的）—— 代理本身不可用或拦截了请求
        errMsg =
          `403 Forbidden — this error is from a CORS proxy, not DeepL. ` +
          `The proxy (${final.via}) blocked the request before it reached DeepL. ` +
          `Tried ${failedAttempts.length} route(s): ${failedAttempts.join(', ')}. ` +
          `DeepL API cannot be called directly from the browser due to CORS restrictions. ` +
          `Tip: Use MyMemory as your default provider (it works directly in the browser), ` +
          `or set up a backend/server-side proxy for DeepL.`;
      } else if (isFromDeepL) {
        // 403 确实是 DeepL 返回的 → Key 或 Plan 有问题
        errMsg =
          '403 Forbidden — DeepL rejected the API key. ' +
          'Please check: (1) your API key is correct, ' +
          '(2) you selected the right plan (Free vs Pro — they use different API endpoints), ' +
          '(3) the key has not expired or been revoked.';
      } else {
        // 无法确定来源的 403
        errMsg = `403 Forbidden — request rejected. Response body: ${errBody.slice(0, 150)}`;
      }
    } else if (status === 429) {
      errMsg = '429 Too Many Requests — rate limit exceeded, slow down';
    } else if (status === 456) {
      errMsg = '456 Quota Exceeded — you have used all your DeepL characters for this billing period';
    } else if (status === 401) {
      errMsg = '401 Unauthorized — authentication failed (check your API key or CORS proxy key)';
    } else if (errBody) {
      errMsg = `HTTP ${status}: ${errBody.slice(0, 200)}`;
    }
    logger.error(`[Translate] DeepL error: ${errMsg}`);
    throw new Error(`DeepL: ${errMsg}`);
  }

  // 全部都是网络/CORS 错误
  // V135: 针对不同失败场景给出更具体的排查指引
  const hasCustomProxy = failedAttempts.includes('custom-proxy');
  const hasCorsProxies = failedAttempts.some(a => a.startsWith('proxy:'));

  let debugTips = '';
  if (hasCustomProxy) {
    debugTips =
      '\n\n🔧 Custom Proxy Troubleshooting:\n' +
      '  1. Verify your Worker is deployed and accessible (visit the URL in browser)\n' +
      '  2. Check the Worker returned CORS headers contain: Access-Control-Allow-Origin: *\n' +
      '  3. Ensure the Worker handles OPTIONS preflight requests (returns 204)\n' +
      '  4. Worker code must include Content-Type and Authorization in Allow-Headers\n' +
      '  5. Latest Worker code is in public/docs/deepl-proxy-worker.js — redeploy if needed';
  } else if (hasCorsProxies) {
    debugTips =
      '\n\n💡 Tip: Public CORS proxies are unreliable. For stable DeepL translation,\n' +
      '     set up a Cloudflare Worker proxy (see docs/ for setup guide).';
  } else {
    debugTips =
      '\n\n💡 Tip: Enable "Use CORS Proxy" in Translate Settings, or set up a\n' +
      '     Cloudflare Worker for reliable DeepL access from the browser.';
  }

  const friendlyMsg =
    `Network/CORS error — DeepL API call failed via all ${failedAttempts.length} available routes ` +
    `(${failedAttempts.join(', ')}). ` +
    'DeepL API does not support direct browser calls due to CORS restrictions. ' +
    'The app will automatically fall back to MyMemory for translation.' +
    debugTips;
  logger.error(`[Translate] DeepL all routes failed (network/CORS). Attempts: ${failedAttempts.join(' → ')}. Last error: ${final.error}`);
  throw new Error(`DeepL: ${friendlyMsg}`);
}

/* ---------- MyMemory 翻译 ---------- */

async function translateWithMyMemory(
  text: string,
  from: LangCode,
  to: LangCode,
): Promise<string> {
  const url =
    `https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}` +
    `&langpair=${MYMEMORY_LANG_MAP[from]}|${MYMEMORY_LANG_MAP[to]}`;

  const res = await fetch(url);
  if (!res.ok) throw new Error(`MyMemory HTTP ${res.status}`);
  const data = await res.json();
  const translated: string = data?.responseData?.translatedText ?? '';
  if (!translated) throw new Error('MyMemory: empty result');
  if (data?.responseStatus && data.responseStatus !== 200) {
    throw new Error(
      `MyMemory ${data.responseStatus}: ${data.responseDetails || 'rate limited'}`,
    );
  }
  return translated;
}

/* ---------- 统一翻译入口 ---------- */

/**
 * 翻译单段文本
 * @returns 翻译后的文本；失败时返回原文
 * @throws 仅当所有引擎都彻底失败时抛出（网络错误等）；降级回退成功不抛
 */
export async function translateText(
  text: string,
  from: LangCode,
  to: LangCode,
): Promise<{ text: string; succeeded: boolean }> {
  const trimmed = text.trim();
  if (!trimmed) return { text: '', succeeded: true };
  if (from === to) return { text, succeeded: true };

  const key = cacheKey(from, to, trimmed);
  const c = getCache();
  if (c[key]) return { text: c[key], succeeded: true };

  const settings = getTranslateSettings();
  let result: string | null = null;
  let lastError: Error | null = null;

  // 1. 优先 DeepL（如果配置了 Key）
  if (settings.provider === 'deepl' && settings.deeplApiKey) {
    try {
      await deeplLimiter.acquire();
      result = await translateWithDeepL(
        trimmed,
        from,
        to,
        settings.deeplApiKey,
        settings.deeplPlan,
        settings.useCorsProxy,
        settings.corsProxyApiKey,
        settings.customProxyUrl,
      );
    } catch (e) {
      lastError = e as Error;
      logger.warn(`DeepL translate failed [${from}->${to}]: ${String(e)}`);
      // DeepL 失败自动降级到 MyMemory
    }
  }

  // 2. MyMemory（兜底或默认）
  if (!result) {
    try {
      await mymemoryLimiter.acquire();
      result = await translateWithMyMemory(trimmed, from, to);
    } catch (e) {
      lastError = e as Error;
      logger.warn(`MyMemory translate failed [${from}->${to}]: ${String(e)}`);
    }
  }

  // 3. 全部失败返回原文，标记失败
  if (!result) {
    const msg = `All translation providers failed [${from}->${to}]: ${lastError?.message || 'unknown'}`;
    logger.warn(msg);
    return { text: trimmed, succeeded: false };
  }

  // 写入缓存
  c[key] = result;
  saveCache();
  return { text: result, succeeded: true };
}

/**
 * 批量翻译多个文本（相同源→目标，并发受限流器约束）
 */
export async function translateBatch(
  texts: string[],
  from: LangCode,
  to: LangCode,
  onProgress?: (current: number, total: number) => void,
): Promise<string[]> {
  const results: string[] = [];
  for (let i = 0; i < texts.length; i++) {
    const { text } = await translateText(texts[i], from, to);
    results.push(text);
    onProgress?.(i + 1, texts.length);
  }
  return results;
}

export interface TranslateAllResult {
  zh: string;
  es: string;
  ja: string;
  /** 有多少种语言真正翻译成功（返回值 != 原文） */
  changedCount: number;
  /** 各翻译引擎是否至少有一个返回了结果（非完全失败） */
  anyProviderSucceeded: boolean;
}

/**
 * 一次性翻译到三种语言（zh/es/ja）
 */
export async function translateToAll(text: string): Promise<TranslateAllResult> {
  const trimmed = text.trim();
  if (!trimmed) {
    return { zh: '', es: '', ja: '', changedCount: 0, anyProviderSucceeded: true };
  }
  const [zhRes, esRes, jaRes] = await Promise.all([
    translateText(trimmed, 'en', 'zh'),
    translateText(trimmed, 'en', 'es'),
    translateText(trimmed, 'en', 'ja'),
  ]);
  const zh = zhRes.text;
  const es = esRes.text;
  const ja = jaRes.text;
  const changedCount =
    (zh !== trimmed ? 1 : 0) + (es !== trimmed ? 1 : 0) + (ja !== trimmed ? 1 : 0);
  const anyProviderSucceeded = zhRes.succeeded || esRes.succeeded || jaRes.succeeded;
  return { zh, es, ja, changedCount, anyProviderSucceeded };
}

/**
 * 测试 DeepL API Key 是否有效
 */
export async function testDeepLKey(
  apiKey: string,
  plan: 'free' | 'pro',
  useCorsProxy: boolean,
  corsProxyApiKey = '',
  customProxyUrl = '',
): Promise<{ ok: boolean; message: string }> {
  if (!apiKey.trim()) {
    return { ok: false, message: 'API Key is required' };
  }
  try {
    const result = await translateWithDeepL(
      'Hello',
      'en',
      'zh',
      apiKey.trim(),
      plan,
      useCorsProxy,
      corsProxyApiKey,
      customProxyUrl,
    );
    return { ok: true, message: `API Key is valid. Test translation: ${result}` };
  } catch (e) {
    return { ok: false, message: String((e as Error).message || e) };
  }
}

/**
 * 测试自定义代理连接（单独测试 CORS 和健康状态，不依赖 DeepL API Key）
 * - 先发 GET 到代理根路径 / 或 /health，检查是否返回健康状态
 * - 如果健康检查通过，再发一个 OPTIONS preflight 检查 CORS
 */
export async function testProxyConnection(
  customProxyUrl: string,
): Promise<{ ok: boolean; message: string; details?: string }> {
  const trimmed = customProxyUrl.trim().replace(/\/+$/, '');
  if (!trimmed) {
    return { ok: false, message: 'Proxy URL is empty' };
  }
  if (!/^https?:\/\/.+/.test(trimmed)) {
    return { ok: false, message: 'Proxy URL must start with http:// or https://' };
  }

  const healthUrl = trimmed.endsWith('/health') ? trimmed : `${trimmed}/health`;
  const rootUrl = trimmed;

  try {
    // 1. 健康检查（GET，simple request，不会触发 preflight）
    //    用 GET /health 或 GET / 探测 Worker 是否在线
    logger.info(`[Translate] Proxy health check: GET ${healthUrl}`);
    let healthOk = false;
    let healthBody = '';
    let corsOk = false;
    let acaoHeader = '';

    try {
      const res = await fetch(healthUrl, { method: 'GET' });
      acaoHeader = res.headers.get('access-control-allow-origin') || '';
      healthBody = await res.text().catch(() => '');
      healthOk = res.ok;
      // 如果 GET 返回了 Access-Control-Allow-Origin，说明 CORS 基本没问题
      if (acaoHeader === '*' || acaoHeader.includes(window.location.origin)) {
        corsOk = true;
      }
      logger.info(
        `[Translate] Proxy health check: HTTP ${res.status}, ` +
        `ACAO=${acaoHeader || '(none)'}, ` +
        `bodyLen=${healthBody.length}`
      );
    } catch (healthErr) {
      // GET 也失败 → 代理可能不在线或 URL 错误
      const msg = healthErr instanceof Error ? healthErr.message : String(healthErr);
      logger.error(`[Translate] Proxy health check failed: ${msg}`);
      return {
        ok: false,
        message: 'Proxy is unreachable (GET /health failed)',
        details: `Error: ${msg}\n\nPossible causes:\n  - Wrong Worker URL\n  - Worker not deployed\n  - Network connectivity issue\n  - Worker is on a different domain without CORS headers`,
      };
    }

    // 2. 如果健康检查通过但 CORS 头缺失，检查一下 POST 会不会触发 CORS
    //    （Authorization header 会触发 preflight）
    //    这里我们不直接测 POST（因为没 Key），而是检查 OPTIONS
    if (healthOk && !corsOk) {
      // 手动发一个 OPTIONS preflight 检查
      logger.info(`[Translate] Proxy CORS preflight check: OPTIONS ${trimmed}`);
      try {
        const preflightRes = await fetch(trimmed, {
          method: 'OPTIONS',
          headers: {
            // 模拟浏览器 preflight 会发的请求头
            'Access-Control-Request-Method': 'POST',
            'Access-Control-Request-Headers': 'content-type,authorization',
          },
        });
        const allowHeaders = preflightRes.headers.get('access-control-allow-headers') || '';
        const allowMethods = preflightRes.headers.get('access-control-allow-methods') || '';
        const allowOrigin = preflightRes.headers.get('access-control-allow-origin') || '';
        logger.info(
          `[Translate] Proxy preflight response: HTTP ${preflightRes.status}, ` +
          `ACAO=${allowOrigin || '(none)'}, ` +
          `ACAM=${allowMethods || '(none)'}, ` +
          `ACAH=${allowHeaders || '(none)'}`
        );
        if (preflightRes.ok && (allowOrigin === '*' || allowOrigin.includes(window.location.origin))) {
          corsOk = true;
        }
      } catch (preErr) {
        logger.warn(`[Translate] Proxy preflight check failed: ${String(preErr)}`);
      }
    }

    // 3. 汇总结果
    if (healthOk && corsOk) {
      return {
        ok: true,
        message: 'Proxy connection is healthy and CORS is configured correctly',
        details: `Health check: OK (${healthBody.slice(0, 100)}...)\nCORS: OK (Access-Control-Allow-Origin: ${acaoHeader || '*'})`,
      };
    } else if (healthOk && !corsOk) {
      return {
        ok: false,
        message: 'Proxy is online but CORS headers are missing or incorrect',
        details:
          'The Worker responded to the health check, but CORS headers are not properly set.\n\n' +
          'To fix this, make sure your Worker code includes:\n' +
          '  - OPTIONS handler returning status 204\n' +
          '  - Access-Control-Allow-Origin: *\n' +
          '  - Access-Control-Allow-Headers: Content-Type, Authorization\n' +
          '  - Access-Control-Allow-Methods: GET, POST, OPTIONS\n\n' +
          'Redeploy your Worker with the latest code from the "View Worker Code" button.',
      };
    } else {
      return {
        ok: false,
        message: `Proxy health check failed (HTTP error)`,
        details: `The Worker returned an error response.\nHealth endpoint: ${healthUrl}\nResponse: ${healthBody.slice(0, 200)}`,
      };
    }
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    return {
      ok: false,
      message: 'Proxy connection test failed',
      details: `Error: ${msg}`,
    };
  }
}

/**
 * 清空翻译缓存
 */
export function clearTranslationCache() {
  cache = {};
  try {
    localStorage.removeItem(CACHE_KEY);
  } catch {
    // ignore
  }
}

/* ---------- 批量翻译 I18nText ---------- */

export interface BatchI18nTask {
  /** 字段名 / 描述，用于进度显示与失败清单 */
  label: string;
  /** 待翻译的多语言文本 */
  value: I18nText;
  /** 如果非英文已有翻译是否跳过（默认 true） */
  skipIfTranslated?: boolean;
}

export interface BatchI18nResult {
  label: string;
  value: I18nText;
  skipped: boolean;
  success: boolean;
  error?: string;
}

/**
 * 批量翻译多个 I18nText 字段（英→中/西/日）
 * - 顺序处理（受限于流内部的令牌桶）
 * - 已有翻译的字段默认跳过
 * - 支持进度回调
 * - 单字段失败不影响其他字段
 */
export async function batchTranslateI18n(
  tasks: BatchI18nTask[],
  onProgress?: (current: number, total: number, label: string) => void,
): Promise<BatchI18nResult[]> {
  const results: BatchI18nResult[] = [];
  const total = tasks.length;

  for (let i = 0; i < tasks.length; i++) {
    const task = tasks[i];
    const { value, label, skipIfTranslated = true } = task;
    const en = value.en.trim();

    if (!en) {
      results.push({ label, value, skipped: true, success: false });
      onProgress?.(i + 1, total, label);
      continue;
    }

    // 检查是否已有全部翻译
    if (skipIfTranslated && value.zh.trim() && value.es.trim() && value.ja.trim()) {
      results.push({ label, value, skipped: true, success: true });
      onProgress?.(i + 1, total, label);
      continue;
    }

    try {
      const r = await translateToAll(en);
      const newValue: I18nText = {
        en,
        zh: value.zh.trim() || r.zh,
        es: value.es.trim() || r.es,
        ja: value.ja.trim() || r.ja,
      };
      // 成功判定：至少一个引擎返回了结果（非全部失败）
      // 即便短文本/专有名词 changedCount 为 0（目标语=源语），只要 provider 正常响应就不算失败
      const ok = r.anyProviderSucceeded;
      results.push({ label, value: newValue, skipped: false, success: ok });
    } catch (e) {
      // 失败则保留原文
      results.push({
        label,
        value,
        skipped: false,
        success: false,
        error: String((e as Error)?.message || e),
      });
      logger.warn(`Batch translate failed [${label}]: ${String(e)}`);
    }

    onProgress?.(i + 1, total, label);
  }

  return results;
}
